def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(v == c for row in grid for v in row) for c in range(10)]
    bg = max(range(10), key=lambda c: counts[c])

    # Uniform non-background rows and columns are dividers.
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]
    divider_colors = {grid[r][0] for r in sep_rows}
    divider_colors.update(grid[0][c] for c in sep_cols)

    def blocks(n, dividers):
        result = []
        start = 0
        for p in dividers:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < n:
            result.append((start, n))
        return result

    row_blocks = blocks(h, sep_rows)
    col_blocks = blocks(w, sep_cols)

    # The patterned block is the one with the most non-background content.
    source = max(
        ((i, j) for i in range(len(row_blocks))
                 for j in range(len(col_blocks))),
        key=lambda ij: sum(
            grid[r][c] != bg and grid[r][c] not in divider_colors
            for r in range(*row_blocks[ij[0]])
            for c in range(*col_blocks[ij[1]])
        )
    )

    sr0, sr1 = row_blocks[source[0]]
    sc0, sc1 = col_blocks[source[1]]
    th, tw = sr1 - sr0, sc1 - sc0

    out = [row[:] for row in grid]
    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[sr0 + (r - r0) % th][sc0 + (c - c0) % tw]
    return out
